// Lê o evento da Evolution, guarda histórico por contacto e aprende com as respostas reais do Tomás
const body = $input.first().json.body || {};
if ((body.event || '').toLowerCase() !== 'messages.upsert') return [];
const canal = body.canal || 'evolution'; // 'evolution' (723) ou 'meta' (número novo, API oficial)
const d = body.data || {};
const key = d.key || {};
const jid = key.remoteJid || '';
if (!jid || jid.endsWith('@g.us') || jid === 'status@broadcast' || jid.endsWith('@newsletter')) return [];
const m = d.message || {};
const texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || (m.imageMessage && m.imageMessage.caption) || '';
if (!texto) return [];
const alvo = key.remoteJidAlt || key.senderPn || jid;
const numero = alvo.split('@')[0].split(':')[0];
const MEU_NUMERO = '351967117357'; // número do Tomás que recebe os rascunhos

const mem = $getWorkflowStaticData('global');
mem.h = mem.h || {};
mem.pend = mem.pend || {};
mem.ex = mem.ex || [];

if (numero === MEU_NUMERO) {
  if (key.fromMe) return []; // rascunhos e confirmações enviados pelo próprio fluxo
  // Comando do Tomás: responder a um rascunho com OK (envia), X (ignora) ou outro texto (envia esse texto)
  const ctx = (m.extendedTextMessage && m.extendedTextMessage.contextInfo) || {};
  const q = ctx.quotedMessage || {};
  const citado = q.conversation || (q.extendedTextMessage && q.extendedTextMessage.text) || '';
  const achado = citado.match(/\(\+(\d+)\)/);
  const destino = achado ? achado[1] : mem.ultimo;
  if (!destino || !mem.pend[destino] || mem.pend[destino].enviado) return [];
  const cmd = texto.trim().toLowerCase();
  if (cmd === 'x') { delete mem.pend[destino]; return []; }
  const p = mem.pend[destino];
  const envio = cmd === 'ok' ? p.rascunho : texto.trim();
  p.enviado = true; // evita enviar duas vezes
  if (p.canal === 'meta') {
    // A API oficial não devolve eco das mensagens enviadas: o exemplo de treino fica já aqui
    mem.ex.push({ cliente: p.cliente, rascunho: p.rascunho, real: envio });
    mem.ex = mem.ex.slice(-30);
    delete mem.pend[destino];
    const hm = mem.h[destino] || [];
    hm.push({ role: 'assistant', content: envio });
    mem.h[destino] = hm.slice(-12);
  }
  return [{ json: { acao: 'enviar', canal: p.canal || 'evolution', numero: destino, texto: envio } }];
}
const h = mem.h[numero] || [];
h.push({ role: key.fromMe ? 'assistant' : 'user', content: texto });
mem.h[numero] = h.slice(-12);

if (key.fromMe) {
  // Resposta real do Tomás: fica como exemplo de treino ao lado do rascunho do bot
  const p = mem.pend[numero];
  if (p) {
    mem.ex.push({ cliente: p.cliente, rascunho: p.rascunho, real: texto });
    mem.ex = mem.ex.slice(-30);
    delete mem.pend[numero];
  }
  return [];
}

const NL = String.fromCharCode(10);
const msgs = [];
for (const x of mem.h[numero]) {
  if (msgs.length && msgs[msgs.length - 1].role === x.role) msgs[msgs.length - 1].content += NL + x.content;
  else msgs.push({ ...x });
}
while (msgs.length && msgs[0].role !== 'user') msgs.shift();

// Os últimos exemplos reais do Tomás entram no prompt: o bot imita o tom e as decisões dele
let system = $('Prompt').first().json.system;
const ult = mem.ex.slice(-8);
if (ult.length) {
  system += NL + NL + 'Exemple reale (cum a răspuns Tomás; imită tonul și deciziile lui, nu ciorna):' + NL +
    ult.map((e, i) => `${i + 1}. Client: ${e.cliente}${NL}   Ciorna ta: ${e.rascunho}${NL}   Tomás a trimis: ${e.real}`).join(NL);
}

return [{ json: {
  acao: 'rascunho', canal, numero, nome: d.pushName || '', texto,
  payload: { model: 'claude-haiku-5-5', max_tokens: 1000, thinking: { type: 'disabled' }, system, messages: msgs }
}}];

const r = $input.first().json;
const c = $('Extrair e memória').first().json;
const NL = String.fromCharCode(10);
const bloco = (r.content || []).find(x => x.type === 'text');
// Se o Claude não devolver texto, mostra o motivo no rascunho
const bruto = bloco ? bloco.text : '⚠️ Claude sem texto: ' + JSON.stringify(r).slice(0, 400);
const [parteCliente, partePT = ''] = bruto.split('###PT###');
const pessoa = bruto.includes('[PESSOA]');
const resposta = parteCliente.replace('[PESSOA]', '').trim();
const tCliente = (partePT.match(/Cliente:\s*(.*)/) || [])[1] || '';
const tResposta = (partePT.match(/Resposta:\s*(.*)/) || [])[1] || '';

// Guarda o rascunho para o comparar com o que o Tomás enviar de facto
const mem = $getWorkflowStaticData('global');
mem.pend = mem.pend || {};
if (bloco) { mem.pend[c.numero] = { cliente: c.texto, rascunho: resposta, canal: c.canal }; mem.ultimo = c.numero; }

const linhas = [
  pessoa ? '🙋 PRECISA DE TI' : '📝 RASCUNHO',
  `De: ${c.nome} (+${c.numero})` + (c.canal === 'meta' ? ' · 📱 Meta' : ''),
  '',
  `Mensagem: ${c.texto}`,
  tCliente ? `🇵🇹 ${tCliente}` : null,
  '',
  'Resposta proposta:',
  resposta,
  tResposta ? `🇵🇹 ${tResposta}` : null,
  '',
  'Responde a esta mensagem com OK (envia), X (ignora) ou o teu texto.',
  c.canal === 'meta' ? null : `Abrir conversa: https://wa.me/${c.numero}`,
].filter(l => l !== null);
return [{ json: { texto: linhas.join(NL) } }];

// Converte o evento da API oficial da Meta para o mesmo formato da Evolution
const out = [];
for (const it of $input.all()) {
  const b = it.json.body || {};
  for (const e of b.entry || []) for (const ch of e.changes || []) {
    const v = ch.value || {};
    const nomes = {};
    for (const c of v.contacts || []) nomes[c.wa_id] = (c.profile && c.profile.name) || '';
    for (const msg of v.messages || []) {
      const t = (msg.text && msg.text.body) || (msg.button && msg.button.text) ||
        (msg.interactive && ((msg.interactive.button_reply && msg.interactive.button_reply.title) || (msg.interactive.list_reply && msg.interactive.list_reply.title))) || '';
      if (!t) continue;
      out.push({ json: { body: { event: 'messages.upsert', canal: 'meta', data: {
        key: { remoteJid: msg.from + '@s.whatsapp.net', fromMe: false },
        pushName: nomes[msg.from] || '', message: { conversation: t } } } } });
    }
  }
}
return out;
